-- Create "feeds" table
CREATE TABLE `feeds` (`id` int unsigned NOT NULL AUTO_INCREMENT, `label` varchar(255) NOT NULL, `path` varchar(255) NOT NULL, `format` varchar(16) NOT NULL DEFAULT 'rss', `status` tinyint NOT NULL DEFAULT 1, `content_types` varchar(1024) NOT NULL DEFAULT '', `term_ids` varchar(1024) NOT NULL DEFAULT '', `item_limit` int NOT NULL DEFAULT 50, `days` int NOT NULL DEFAULT 0, `title` varchar(255) NOT NULL DEFAULT '', `description` varchar(255) NOT NULL DEFAULT '', `language` varchar(8) NOT NULL DEFAULT '', `image_style` varchar(64) NOT NULL DEFAULT '', `created_at` datetime NOT NULL, `updated_at` datetime NOT NULL, PRIMARY KEY (`id`), UNIQUE INDEX `feeds_path` (`path`)) CHARSET utf8mb4 COLLATE utf8mb4_unicode_ci;
-- Create "feed_field_maps" table
CREATE TABLE `feed_field_maps` (`id` int unsigned NOT NULL AUTO_INCREMENT, `feed_id` int unsigned NOT NULL, `content_type` varchar(64) NOT NULL, `body_field` varchar(64) NOT NULL DEFAULT '', `image_field` varchar(64) NOT NULL DEFAULT '', `category_field` varchar(64) NOT NULL DEFAULT '', PRIMARY KEY (`id`), UNIQUE INDEX `feed_field_maps_feed_type` (`feed_id`, `content_type`)) CHARSET utf8mb4 COLLATE utf8mb4_unicode_ci;
